const SPEECH_LANGUAGE = 'en-IN';

const RECOGNITION_ERRORS = {
  'not-allowed': 'Microphone permission was denied. Allow microphone access in browser settings, or type your message.',
  'service-not-allowed': 'Speech recognition is blocked by this browser or its policies. You can still type.',
  'audio-capture': 'No working microphone was found. Check your microphone connection and settings.',
  network: 'The speech service could not be reached. Check your connection or type your message.',
  'no-speech': 'No speech was detected. Try again and speak clearly, or type your message.',
  'language-not-supported': 'English speech recognition is not supported by your browser. You can still type your message.',
};

export function findSpeechVoice(voices) {
  const tag = SPEECH_LANGUAGE.toLowerCase();
  return voices.find((voice) => voice.lang.toLowerCase() === tag)
    || voices.find((voice) => voice.lang.toLowerCase().split('-')[0] === tag.split('-')[0]);
}

export function createChatSpeech({ onTranscript, onState, onError }) {
  let recognition = null;
  let utterance = null;
  let sessionId = 0;

  const publish = () => onState({ listening: recognition !== null, speaking: utterance !== null });

  const cancel = () => {
    sessionId += 1;
    if (recognition) {
      const previous = recognition;
      recognition = null;
      previous.onresult = previous.onerror = previous.onend = null;
      try {
        previous.abort();
      } catch {
        console.error('Microphone recognition could not be stopped.');
        onError('The microphone could not be stopped. Close this page or revoke microphone access in browser settings.');
      }
    }
    if (utterance) {
      utterance.onend = utterance.onerror = null;
      utterance = null;
      window.speechSynthesis.cancel();
    }
    publish();
  };

  const stopListening = () => {
    if (!recognition) return;
    try {
      recognition.stop();
    } catch {
      cancel();
      onError('Voice input could not finish. Review the text and try again if needed.');
    }
  };

  const startListening = (draft) => {
    cancel();
    onError('');
    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!window.isSecureContext || !Recognition) {
      onError('Voice input requires a supported browser on HTTPS or localhost. You can still type your message.');
      return;
    }
    if (draft.length >= 4000) {
      onError('The message has reached the 4,000-character limit. Shorten it before adding voice input.');
      return;
    }
    try {
      const current = new Recognition();
      recognition = current;
      current.lang = SPEECH_LANGUAGE;
      current.continuous = false;
      current.interimResults = true;
      let receivedSpeech = false;
      current.onresult = (event) => {
        if (recognition !== current) return;
        const transcript = Array.from(event.results, (result) => result[0].transcript).join(' ').trim();
        if (!transcript) return;
        receivedSpeech = true;
        const text = [draft.trim(), transcript].filter(Boolean).join(' ');
        onTranscript(text.slice(0, 4000));
        if (text.length > 4000) {
          onError('Voice input reached the 4,000-character limit. Review the shortened message before sending.');
          stopListening();
        }
      };
      current.onerror = (event) => {
        if (recognition !== current) return;
        recognition = null;
        current.onresult = current.onerror = current.onend = null;
        onError(RECOGNITION_ERRORS[event.error] || 'Voice input failed. Please try again or type your message.');
        publish();
      };
      current.onend = () => {
        if (recognition !== current) return;
        recognition = null;
        if (!receivedSpeech) onError(RECOGNITION_ERRORS['no-speech']);
        publish();
      };
      publish();
      current.start();
    } catch {
      cancel();
      onError('Voice input could not start. Check microphone permissions and browser support.');
    }
  };

  const speak = (text, expectedSession = sessionId) => {
    if (expectedSession !== sessionId) return;
    cancel();
    onError('');
    if (!window.speechSynthesis || !window.SpeechSynthesisUtterance) {
      onError('Spoken replies are not supported by this browser. The written reply is still available.');
      return;
    }
    try {
      const voice = findSpeechVoice(window.speechSynthesis.getVoices());
      if (!voice) {
        onError('No English voice is currently available. Install or enable an English browser/system voice. The written reply is still available.');
        return;
      }
      const current = new window.SpeechSynthesisUtterance(text);
      utterance = current;
      current.lang = voice.lang;
      current.voice = voice;
      current.onend = () => {
        if (utterance !== current) return;
        utterance = null;
        publish();
      };
      current.onerror = () => {
        if (utterance !== current) return;
        utterance = null;
        onError('The reply could not be read aloud. The written reply is still available.');
        publish();
      };
      publish();
      window.speechSynthesis.speak(current);
    } catch {
      cancel();
      onError('Spoken playback could not start. The written reply is still available.');
    }
  };

  return {
    startListening, stopListening, speak, cancel,
    get sessionId() { return sessionId; },
  };
}
